        /// </summary>
        /// <param name="nums">The binary array</param>
        /// <returns>The maximum number of consecutive 1's</returns>
        static int FindMaxConsecutiveOnes(int[] nums)
        {
            int maxCount = 0;
            int count = 0;

            // Loop through the binary array
            foreach (int num in nums)
            {
                if (num == 1)
                {
                    count++;
                }
                else
                {
                    maxCount = Math.Max(maxCount, count);
                    count = 0;
                }
            }

            // Check the count after looping through the entire array
            maxCount = Math.Max(maxCount, count);

            return maxCount;
        }
    }
}
